#!/usr/bin/env python3
"""
Round 174b (culprits), 4 October 2026. Needs round 173b.

One colour for a layer or a heading (the lost round 147b).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 174b (4 October)\n\nNeeds round 173b (guards on its heading). No tiles patch. No app.js?v= bump.\nRedoes the lost round 147b's colour boxes.\n\n- One colour for a layer: each ticked row's tools (beside the transparency\n  bar) carry a colour box and \"As drawn\". One colour for a heading: each\n  heading's line carries the same pair, colouring every ticked layer under it\n  (nested headings included) and setting their own boxes to match.\n- rowTint / tintPaints: fills take the colour and their outlines and lines a\n  darker shade (x0.6); lines alone take it; dots, glow cores and soft rings\n  take it, the haze a ramp to it; extrusions take it; pictures are turned by\n  raster-hue-rotate from hue 200 to the colour's hue. Each layer's own value\n  is kept in TINT_ORIG and put back by \"As drawn\".\n- TINT_RAW: the first setPaintProperty hook passes a chosen colour straight\n  through, so the map-wide colour mapping (gladpx) and the themes leave it\n  alone. tintKeep, on the map's idle, colours layers that arrive later or\n  were repainted by a theme.\n- Not seen in a browser: the map never fires \"load\" in the sandbox.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round174b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 173b" not in h.read_text(encoding="utf-8"):
        sys.exit("round174b: round 173b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round174b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round174b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round174b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
